export const GUIDE_DIAGRAMS=freeze(DIAGRAM_DATA);
export const GUIDE_TOPICS=freeze(SOURCE_TOPICS.map(topic=>{
  const aid=GUIDE_LESSONS[topic.id];
  if(!aid)throw new Error('Missing learning aid for '+topic.id);
  return {...topic,...aid,title_he:topic.title,title_en:null,app_section:GUIDE_SECTIONS.find(section=>section.id===topic.category).title_en,
    source_kind:GUIDE_SOURCE_INFO.sourceKind,original_explanation_he:topic.body,
    source:{file:GUIDE_SOURCE_INFO.file,sha256:GUIDE_SOURCE_INFO.sha256,lines:topic.sourceLines},
    coverage:{...aid.coverage,note:GUIDE_COVERAGE[aid.coverage.status].description},
    examples:[aid.example,aid.counterexample],
    sourceExercises:aid.sourceExerciseIds.map(id=>GUIDE_SOURCE_EXERCISES.find(exercise=>exercise.id===id)),
    diagramData:aid.diagrams.map(id=>({id,...GUIDE_DIAGRAMS[id]})),
  };
}));
const normalize=value=>String(value??'').normalize('NFKD').replace(/[\u0591-\u05C7]/g,'').toLocaleLowerCase('he').replace(/[׳״'"–—-]/g,' ').replace(/\s+/g,' ').trim();
const SEARCH_TEXT=new Map(GUIDE_TOPICS.map(topic=>[topic.id,normalize([topic.id,topic.title,topic.body,topic.explanation,...topic.formulas,...topic.variants.flatMap(variant=>[variant.name,variant.description]),topic.exercise.question,topic.exercise.answer].join(' '))]));
export function getGuideTopic(id){return GUIDE_TOPICS.find(topic=>topic.id===String(id))??null;}
export function searchGuideTopics(query='',options={}){
  const words=normalize(query).split(' ').filter(Boolean);
  return GUIDE_TOPICS.filter(topic=>(!options.category||topic.category===Number(options.category))&&(!options.status||topic.coverage.status===options.status)&&words.every(word=>SEARCH_TEXT.get(topic.id).includes(word)));
}
